@pytest.mark.xfail(strict=True)
def test_case_1():
    var_0 = 'rZHO"~kvi3Q;H'
    var_1 = None
    module_0.import_statement(var_0, var_0, config=var_1, explode=var_0)

@pytest.mark.xfail(strict=True)
def test_case_2():
    var_0 = None
    module_0.import_statement(var_0, var_0, multi_line_output=var_0)

