def test_case_11():
    var_0 = 20
    var_1 = 3
    var_2 = True
    var_3 = '  #'
    var_4 = 'line_length'
    var_5 = 'multi_line_output'
    var_6 = 'use_parentheses'
    var_7 = 'include_trailing_comma'
    var_8 = 'comment_prefix'
    var_9 = {var_4: var_0, var_5: var_1, var_8: var_0, var_6: var_2, var_7: var_2, var_8: var_3}
    var_10 = module_3.Config(**var_9)
    assert f'{type(var_10).__module__}.{type(var_10).__qualname__}' == 'isort.settings.Config'
    assert var_10.py_version == 'py3'
    assert f'{type(var_10.force_to_top).__module__}.{type(var_10.force_to_top).__qualname__}' == 'builtins.frozenset'
    assert len(var_10.force_to_top) == 0
